/** Names that reuse an existing brand glyph. */
const aliases: Record<string, string> = {
  "Shopify Apps": "Shopify",
  "Shopify Themes": "Shopify",
  "WooCommerce": "WordPress",
  "Cloudflare R2": "Cloudflare",
  "Cloudflare Workers": "Cloudflare",
  "React.js": "React",
  "Express.js": "Express",
  "REST APIs": "REST API",
  "Tailwind": "Tailwind CSS",
  "Node": "Node.js",
  "AI Automation": "OpenAI",
  "Assistants": "OpenAI",
  "RAG": "OpenAI",
  "Vector Search": "OpenAI",
  "Prompt Engineering": "OpenAI",
  "LangChain": "OpenAI",
  "TanStack Router": "React Router",
};

function resolve(name: string) {
  return glyphs[name] ?? glyphs[aliases[name] ?? ""];
}

export function hasGlyph(name: string) {
  return Boolean(resolve(name));
}

export function TechGlyph({
  name,
  className,
  colored = true,
}: {
  name: string;
  className?: string;
  colored?: boolean;
}) {
  const glyph = resolve(name);
  if (!glyph) return null;
  return (
    <svg
      aria-hidden
      viewBox={glyph.viewBox ?? "0 0 24 24"}
      className={className}
      fill={colored ? glyph.hex : "currentColor"}
    >
      <path d={glyph.p} />
    </svg>
  );
}
